/* Soundcheck UI for acoustic audio input; capture starts only on Connect audio. */
(function(root,factory){const setup=factory(typeof module==='object'&&module.exports?require('./audio-drum-core.js'):root.RiffAudioDrumCore);if(typeof module==='object'&&module.exports)module.exports=setup;else root.RiffAudioDrumSetup=setup;})(typeof window==='object'?window:globalThis,Core=>function({document,input}){
 const $=id=>document.getElementById(id);if(!$('audioDrumConnect'))return;
 let list='',settingsKey='',rowKey='';const rows=new Map(),element=(tag,text)=>{const e=document.createElement(tag);if(text)e.textContent=text;return e;};
 function refresh(){$('controllerButton').textContent=input.stream?'Controllers / drums · mic on':'Controllers / drums';const connected=!!input.stream,key=JSON.stringify(input.inputs);if(key!==list){list=key;const selected=$('audioDrumDevice').value;const options=[{id:'',name:'System default audio input'},...input.inputs].map(d=>{const o=element('option',d.name);o.value=d.id;return o;});$('audioDrumDevice').replaceChildren(...options);$('audioDrumDevice').value=input.inputs.some(d=>d.id===selected)?selected:'';}
  const profile=input.deviceKey+':'+connected;if(profile!==settingsKey){settingsKey=profile;$('audioDrumGate').value=String(input.threshold);$('audioDrumLatency').value=String(input.latency);if(connected&&input.inputs.some(d=>d.id===input.deviceKey))$('audioDrumDevice').value=input.deviceKey;}
  $('audioDrumStatus').textContent=input.message+(input.storageError?' '+input.storageError:'');$('audioDrumLevel').value=Math.min(1,input.level*8);$('audioDrumLevelText').textContent=input.clipping?'Clipping: lower the EAD input gain':connected?'Listening · '+(input.name||'audio input'):'Microphone off';
  $('audioDrumConnect').disabled=input.connecting;$('audioDrumConnect').textContent=input.connecting?'Connecting…':connected?'Reconnect selected audio':'Connect audio';$('audioDrumStop').disabled=!connected&&!input.connecting;$('audioDrumDevice').disabled=input.connecting;
  $('audioDrumEnabled').disabled=!connected||!input.ready||!!input.calibration;$('audioDrumEnabled').checked=input.enabled;$('audioDrumLearn').disabled=!connected||!!input.calibration;$('audioDrumCancel').hidden=!input.calibration;$('audioDrumForget').disabled=!connected||!Object.keys(input.templates).length;$('audioDrumGate').disabled=!connected;$('audioDrumLatency').disabled=!connected;
  const rk=JSON.stringify([connected,!!input.calibration,Object.keys(input.templates)]);if(rk!==rowKey){rowKey=rk;rows.clear();$('audioDrumSounds').replaceChildren(...Core.ROLES.map((role,i)=>{const row=element('div');row.className='audio-drum-sound';const label=element('span',Core.LABELS[i]+(input.templates[role]?' · learned':' · needs soundcheck')),button=element('button','Relearn sound');button.className='quiet';button.disabled=!connected||!!input.calibration;button.setAttribute('aria-label','Learn '+Core.LABELS[i]);button.addEventListener('click',()=>input.calibrate(role));row.append(label,button);rows.set(role,row);return row;}));}
 }
 input.onChange=refresh;input.onDetection=result=>{const message=result.clipping?'Clipped hit ignored':result.roles.length?result.roles.map(r=>Core.LABELS[Core.ROLES.indexOf(r)]).join(' + ')+` · ${Math.round(result.confidence*100)}% match`:'Uncertain sound · ignored';$('audioDrumLastHit').textContent=message;for(const role of result.roles){const row=rows.get(role);if(row){row.classList.remove('controller-hit');void row.offsetWidth;row.classList.add('controller-hit');}}};
 $('audioDrumConnect').addEventListener('click',()=>input.start($('audioDrumDevice').value));$('audioDrumStop').addEventListener('click',()=>input.stop());$('audioDrumEnabled').addEventListener('change',()=>input.setEnabled($('audioDrumEnabled').checked));$('audioDrumLearn').addEventListener('click',()=>input.calibrate());$('audioDrumCancel').addEventListener('click',()=>input.cancel());$('audioDrumForget').addEventListener('click',()=>input.forget());
 const settings=()=>input.settings($('audioDrumGate').value,$('audioDrumLatency').value);$('audioDrumGate').addEventListener('change',settings);$('audioDrumLatency').addEventListener('change',settings);
 for(const event of ['close','cancel'])$('controllerDialog').addEventListener(event,()=>input.cancel());refresh();return {refresh};
});
